/// `DTB_DEFAULT_ENTRIES`; null where `getarch.c` has no entry for the core.
pub fn x86_dtb(core: coretypes.X86CoreType) ?i32 {
    return switch (core) {
        .unknown, .p6 => null,
        .katmai, .coppermine, .northwood, .prescott, .banias, .atom, .nehalem, .sandybridge, .haswell, .skylakex, .cooperlake, .sapphirerapids, .p5, .yonah => 64,
        .core2, .penryn, .dunnington => 256,
        .athlon, .opteron, .opteron_sse3 => 32,
        .barcelona, .bulldozer, .piledriver, .steamroller, .excavator, .zen => 48,
        .nano, .viac3 => 128,
        .bobcat => 40,
    };
}

