/// `DTB_DEFAULT_ENTRIES`; null where `getarch.c` has no entry for the core.
pub fn power64_dtb(core: coretypes.PowerCoreType) ?i32 {
    return switch (core) {
        .unknown => null,
        .power6, .power8, .power9, .power10, .power4, .power5, .ppc970, .cell, .ppcg4 => 128,
        .power3 => 256,
        .ppc440, .ppc440fp2 => 64,
    };
}

/// `BUFFER_SIZE` of a core with no table of its own.
pub const power64be_buffer_size: i64 = 256 << 20;

/// `power64`'s tables but where the byte order changes them.
pub fn power64be(core: coretypes.PowerCoreType) ?Table {
    return switch (core) {
        .ppc970 => .{
            .s = .{ .unroll_m = 4, .unroll_n = 4, .p = .{ .fixed = 176 }, .q = .{ .fixed = 512 } },
            .d = .{ .unroll_m = 4, .unroll_n = 4, .p = .{ .fixed = 176 }, .q = .{ .fixed = 256 } },
