            .align_ = 16383,
            .symv_p = 16,
            .buffer_size = 16 << 20,
        },
    };
}

/// `DTB_DEFAULT_ENTRIES`; null where `getarch.c` has no entry for the core.
pub fn wasm_dtb(core: coretypes.WasmCoreType) ?i32 {
    return switch (core) {
        .wasm_generic => null,
        .wasm128_generic => 128,
    };
}

/// `BUFFER_SIZE` of a core with no table of its own.
pub const generic_buffer_size: i64 = 128 << 20;

pub fn generic(core: coretypes.GenericCoreType) ?Table {
    return switch (core) {
        .generic => .{
            .s = .{ .unroll_m = 2, .unroll_n = 2, .q = .{ .fixed = 128 } },
            .d = .{ .unroll_m = 2, .unroll_n = 2, .q = .{ .fixed = 128 } },
            .q = .{ .unroll_m = 2, .unroll_n = 2, .q = .{ .fixed = 128 } },
            .c = .{ .unroll_m = 2, .unroll_n = 2, .q = .{ .fixed = 128 } },
            .z = .{ .unroll_m = 2, .unroll_n = 2, .q = .{ .fixed = 128 } },
            .x = .{ .unroll_m = 1, .unroll_n = 1, .q = .{ .fixed = 128 } },
            .sh = .{ .unroll_m = 8, .unroll_n = 8, .unroll_mn = 32, .p = .{ .fixed = 128 }, .q = .{ .fixed = 12288 }, .r = .{ .fixed = 240 } },
            .b = .{ .unroll_m = 8, .unroll_n = 4, .unroll_mn = 32, .align_k = 1, .p = .{ .fixed = 256 }, .q = .{ .fixed = 256 }, .r = .{ .fixed = 256 } },
            .sb = .{ .unroll_m = 8, .unroll_n = 4, .unroll_mn = 32, .align_k = 1, .p = .{ .fixed = 256 }, .q = .{ .fixed = 256 }, .r = .{ .fixed = 256 } },
            .c3m = .{ .unroll_m = 2, .unroll_n = 2, .p = .{ .fixed = 448 }, .q = .{ .fixed = 224 }, .r = .{ .fixed = 12288 } },
            .z3m = .{ .unroll_m = 2, .unroll_n = 2, .p = .{ .fixed = 224 }, .q = .{ .fixed = 224 }, .r = .{ .fixed = 12288 } },
            .x3m = .{ .p = .{ .fixed = 112 }, .q = .{ .fixed = 224 }, .r = .{ .fixed = 12288 } },
            .symv_p = 16,
            .buffer_size = 128 << 20,
        },
    };
}

/// `DTB_DEFAULT_ENTRIES`; null where `getarch.c` has no entry for the core.
pub fn generic_dtb(core: coretypes.GenericCoreType) ?i32 {
    return switch (core) {
        .generic => 128,
    };
}

/// `BUFFER_SIZE` on alpha, which takes the generic family.
pub const alpha_buffer_size: i64 = 33554432;

/// `BUFFER_SIZE` on csky, which takes the generic family.
pub const csky_buffer_size: i64 = 33554432;

